import { writeFile } from 'node:fs/promises';
import { WEAPONS, PARTS, TOWERS, SPECIES, MUTATIONS, FIRE_LEVELS, COSTS } from '../dist/content.js';
const table=(headers,rows)=>[headers,headers.map(()=> '---'),...rows].map(row=>'| '+row.map(v=>String(v).replaceAll('|','\\|')).join(' | ')+' |').join('\n');
const weaponName=id=>WEAPONS.find(w=>w.id===id).name;
const sections=[
'# Abilities and content catalog',
'> Generated by `npm run docs:catalog` from `dist/content.js`. Do not edit the tables by hand. Values are current prototype tuning, before organ levels, global mutations or discharge modifiers.',
'## Body weapons',
table(['Weapon','Cost (g)','Cooldown (s)','Range','Damage per hit','Behavior'],WEAPONS.map(w=>[w.name,w.cost,w.interval,w.range,w.damage,w.description])),
'Damage is per hit rather than total volley damage. Ribshot emits five projectiles and larval brood emits two. Tongue, blood and scream can hit multiple enemies. Spore has impact/area/pool effects. Consult `engine.js` for exact geometry and secondary effects; these entries are not DPS estimates.',
'## Discharge',
table(['Mode','Shot cost ×','Damage ×','Cooldown ×'],FIRE_LEVELS.map(f=>[f.name,f.cost,f.damage,f.cadence])),
'All ready organs participate in every mode. The lower cooldown multiplier fires faster.',
'## Grafted anatomy',
table(['Part','Default weapon','Anatomical role'],Object.values(PARTS).map(p=>[p.name,weaponName(p.weapon),p.role])),
'Any body part can be re-equipped in the workshop. Its identity, parent link, source species and upgrade level remain on that part.',
'## Towers',
table(['Tower','Build cost (g)','Health','Range','Cooldown (s)','Damage per hit','Weapon'],TOWERS.map(t=>[t.name,t.cost,t.hp,t.range,t.interval,t.damage,weaponName(t.weapon)])),
'## Budding and infrastructure',
table(['Action','Base cost (g)'],Object.entries(COSTS).map(([kind,cost])=>[kind,cost])),
'Tower/colony discounts come from global mutations. Mobile offspring have their own health and allocated mass; recall refunds the surviving health fraction.',
'## Prey and monstrosities',
table(['Name','Group','Base health','Speed','Biomass drop','Attack damage','Possible grafts'],Object.values(SPECIES).map(s=>[s.name,s.group,s.hp,s.speed,s.mass,s.damage,s.parts.map(k=>PARTS[k].name).join(', ')])),
'Enemy health scales with infection stage. Speed/range values use simulation world units; the game UI labels distance as m. A kill creates one identifiable organ plus ordinary remains, not every part in its possible-grafts list.',
'## Run mutations',
table(['Mutation','Category','Effect'],MUTATIONS.map(m=>[m.name,m.tag,m.description])),
'Mutation descriptions are the game-facing text. The canonical apply functions in `content.js` define exact stacking arithmetic. For example Reflex ganglia multiplies cooldown by 0.8; the display text calls this “20% faster.”',
'## Individual organ levels',
'Each organ starts at level 1 and caps at level 5. Upgrades cost 12/24/36/48g. Each added level gives +35% base damage, +8% base range and shot cost, and +12% base firing speed. Equipment changes do not reset the organ’s level or cooldown. See the [GDD](GDD.md#7-upgrades-and-mutations) for formulas.'
];
await writeFile(new URL('../docs/abilities.md',import.meta.url),sections.join('\n\n')+'\n');
console.log('Updated docs/abilities.md from gameplay definitions.');
